const aiResponse = $input.first().json;

let content = '';
if (aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message) {
  content = aiResponse.choices[0].message.content;
} else if (typeof aiResponse.content === 'string') {
  content = aiResponse.content;
} else {
  content = JSON.stringify(aiResponse);
}

let parsed;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch (e) {
  parsed = { origin: 'Centro', destination: 'Centro' };
}

const origin = (parsed.origin || 'Centro').trim();
const destination = (parsed.destination || 'Centro').trim();

// Coordenadas aproximadas de zonas de Tijuana (mock)
const ZONES = {
  'centro': { lat: 32.5283, lon: -117.0187 },
  'zona rio': { lat: 32.5228, lon: -117.0198 },
  'otay': { lat: 32.5297, lon: -116.9664 },
  'otay centenario': { lat: 32.5389, lon: -116.9483 },
  'playas de tijuana': { lat: 32.5259, lon: -117.1219 },
  'la mesa': { lat: 32.5074, lon: -116.9850 },
  'sanchez taboada': { lat: 32.4979, lon: -117.0006 },
  'la presa': { lat: 32.4796, lon: -116.9394 },
};

function normalize(str) {
  return str.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
}

function findZoneCoords(name) {
  const key = normalize(name);
  if (ZONES[key]) return ZONES[key];
  const match = Object.keys(ZONES).find((z) => key.includes(z) || z.includes(key));
  return match ? ZONES[match] : ZONES['centro'];
}

const originCoords = findZoneCoords(origin);

// Base de datos mock de conductores disponibles
const DRIVERS = [
  { name: 'Carlos Ramirez', car: 'Nissan Versa Blanco', plate: 'BCN-1234', lat: 32.5300, lon: -117.0150 },
  { name: 'Mariana Lopez', car: 'Toyota Corolla Gris', plate: 'BCN-5566', lat: 32.5100, lon: -116.9800 },
  { name: 'Jorge Hernandez', car: 'Chevrolet Aveo Rojo', plate: 'BCN-7788', lat: 32.5350, lon: -116.9500 },
  { name: 'Ana Torres', car: 'Kia Rio Azul', plate: 'BCN-9910', lat: 32.5250, lon: -117.1150 },
  { name: 'Luis Dominguez', car: 'Honda City Negro', plate: 'BCN-3321', lat: 32.4950, lon: -117.0050 },
  { name: 'Paola Vega', car: 'Hyundai Accent Plata', plate: 'BCN-4432', lat: 32.4800, lon: -116.9400 },
];

function haversineKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((lat1 * Math.PI) / 180) * Math.cos((lat2 * Math.PI) / 180) * Math.sin(dLon / 2) ** 2;
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

let nearest = null;
let nearestDistance = Infinity;

for (const driver of DRIVERS) {
  const d = haversineKm(originCoords.lat, originCoords.lon, driver.lat, driver.lon);
  if (d < nearestDistance) {
    nearestDistance = d;
    nearest = driver;
  }
}

const AVG_SPEED_KMH = 35;
const etaMinutes = Math.max(1, Math.round((nearestDistance / AVG_SPEED_KMH) * 60));

return [
  {
    json: {
      origin,
      destination,
      driver: {
        name: nearest.name,
        car: nearest.car,
        plate: nearest.plate,
      },
      distanceKm: Math.round(nearestDistance * 10) / 10,
      etaMinutes,
    },
  },
];
